return ['domain'=>NULL,'plural-forms'=>'nplurals=3; plural=(n == 1) ? 0 : ((n % 10 >= 2 && n % 10 <= 4 && (n % 100 < 12 || n % 100 > 14)) ? 1 : 2);','language'=>'pl_PL','project-id-version'=>'DoSieci AI Operator 1.2.0-dev','pot-creation-date'=>'2026-09-25T02:57:32+00:00','po-revision-date'=>'2026-09-25T02:57:32+00:00','messages'=>['DoSieci AI Operator'=>'DoSieci AI Operator','https://dosieci.pl/wtyczki/ai-operator/'=>'https://dosieci.pl/wtyczki/ai-operator/','An AI assistant for WordPress and WooCommerce. You talk in wp-admin, and the operator diagnoses your site and — once you approve it — builds it: creates content, installs themes and plugins, configures settings. Works through the DoSieci License Hub, WordPress\'s own AI connectors, or directly with your own OpenAI/Anthropic key.'=>'Asystent AI dla WordPressa i WooCommerce. Rozmawiasz w wp-adminie, a operator diagnozuje Twoją witrynę i — po Twoim zatwierdzeniu — buduje ją: tworzy treści, instaluje motywy i wtyczki, konfiguruje ustawienia. Działa przez DoSieci License Hub, własne Łączniki AI WordPressa albo bezpośrednio z Twoim własnym kluczem OpenAI/Anthropic.','DoSieci'=>'DoSieci','https://dosieci.pl/'=>'https://dosieci.pl/','Shop'=>'Sklep','Cart'=>'Koszyk','Checkout'=>'Zamówienie','My account'=>'Moje konto','WooCommerce is not fully loaded.'=>'WooCommerce nie jest w pełni załadowany.','A category called “%s” already exists and the builder did not create it. Regenerate the plan to see the conflict.'=>'Istnieje już kategoria „%s”, której kreator nie tworzył. Wygeneruj plan ponownie, aby zobaczyć konflikt.','Product %d does not exist.'=>'Produkt %d nie istnieje.','WooCommerce did not save the product.'=>'WooCommerce nie zapisał produktu.','WooCommerce is not active yet.'=>'WooCommerce nie jest jeszcze aktywny.','No existing product.'=>'Brak istniejącego produktu.','The previous product was deleted.'=>'Poprzedni produkt został usunięty.','The product was edited by hand after the builder’s last change.'=>'Produkt został zmieniony ręcznie po ostatniej zmianie kreatora.','The product already matches the plan.'=>'Produkt jest już zgodny z planem.','Product created by the builder, with no manual changes.'=>'Produkt utworzony przez kreator, bez ręcznych zmian.','WooCommerce is not active.'=>'WooCommerce nie jest aktywny.','WooCommerce %s is active.'=>'WooCommerce %s jest aktywny.','Page “%1$s” works (id %2$d).'=>'Strona „%1$s” działa (id %2$d).','Page “%s” does not exist or is not assigned.'=>'Strona „%s” nie istnieje lub nie jest przypisana.','%1$s: %2$s.'=>'%1$s: %2$s.','%1$s is “%2$s”, expected “%3$s”.'=>'%1$s to „%2$s”, oczekiwano „%3$s”.','Category “%1$s” exists (id %2$d).'=>'Kategoria „%1$s” istnieje (id %2$d).','Category “%s” is missing.'=>'Brak kategorii „%s”.','Product “%s” is missing.'=>'Brak produktu „%s”.','Product “%1$s” has status “%2$s”, but must remain a draft.'=>'Produkt „%1$s” ma status „%2$s”, a musi pozostać szkicem.','Product “%1$s”: expected %2$s, is %3$s.'=>'Produkt „%1$s”: oczekiwano %2$s, jest %3$s.','Product “%s” is filed under different categories than planned.'=>'Produkt „%s” jest w innych kategoriach niż zaplanowano.','Draft “%1$s” — %2$s.'=>'Szkic „%1$s” — %2$s.','Navigation'=>'Nawigacja','No pages to place in the navigation.'=>'Brak stron do umieszczenia w nawigacji.','Contact Form 7 is not active.'=>'Contact Form 7 nie jest aktywny.','Could not create the form template.'=>'Nie udało się utworzyć szablonu formularza.','Contact Form 7 did not save the form.'=>'Contact Form 7 nie zapisał formularza.','%s — contact form'=>'%s — formularz kontaktowy','This site already has a page with this name (id %d) that the builder did not create.'=>'Na witrynie istnieje już strona o tej nazwie (id %d), której kreator nie tworzył.','No existing resource.'=>'Brak istniejącego zasobu.','The taxonomy is not available yet.'=>'Taksonomia nie jest jeszcze dostępna.','A category with this name (id %d) already exists and the builder did not create it.'=>'Istnieje już kategoria o tej nazwie (id %d), której kreator nie tworzył.','The previous resource was deleted.'=>'Poprzedni zasób został usunięty.','The category was edited by hand after the builder’s last change.'=>'Kategoria została zmieniona ręcznie po ostatniej zmianie kreatora.','The category already matches the plan.'=>'Kategoria jest już zgodna z planem.','Category created by the builder, with no manual changes.'=>'Kategoria utworzona przez kreator, bez ręcznych zmian.','The content was edited by hand after the builder’s last change.'=>'Treść została zmieniona ręcznie po ostatniej zmianie kreatora.','The content already matches the plan.'=>'Treść jest już zgodna z planem.','Resource created by the builder, with no manual changes.'=>'Zasób utworzony przez kreator, bez ręcznych zmian.','No verifier for tool “%s”.'=>'Brak weryfikatora dla narzędzia „%s”.','The tool did not return a post ID.'=>'Narzędzie nie zwróciło identyfikatora wpisu.','Post ID %d does not exist in WordPress.'=>'Wpis o id %d nie istnieje w WordPressie.','A different content type was created than planned.'=>'Utworzono inny typ treści niż zaplanowano.','The post status is “%1$s”, expected “%2$s”.'=>'Status wpisu to „%1$s”, oczekiwano „%2$s”.','The page title does not match the plan.'=>'Tytuł strony nie zgadza się z planem.','The page exists, but is empty.'=>'Strona istnieje, ale jest pusta.','The page exists with the expected title and status.'=>'Strona istnieje z oczekiwanym tytułem i statusem.','Post %d does not exist.'=>'Wpis %d nie istnieje.','Field “%s” was not updated.'=>'Pole „%s” nie zostało zaktualizowane.','The post contains the expected changes.'=>'Wpis zawiera oczekiwane zmiany.','The post is in the trash.'=>'Wpis jest w koszu.','The post was not moved to the trash.'=>'Wpis nie trafił do kosza.','Plugin “%s” is not installed.'=>'Wtyczka „%s” nie jest zainstalowana.','Plugin “%s” is installed, but not active.'=>'Wtyczka „%s” jest zainstalowana, ale nieaktywna.','The plugin is installed as planned.'=>'Wtyczka jest zainstalowana zgodnie z planem.','The plugin’s state matches the plan.'=>'Stan wtyczki zgodny z planem.','The plugin’s activation state does not match the plan.'=>'Stan aktywacji wtyczki nie zgadza się z planem.','Theme “%s” is not installed.'=>'Motyw „%s” nie jest zainstalowany.','Theme “%1$s” is installed, but “%2$s” is active.'=>'Motyw „%1$s” jest zainstalowany, ale aktywny jest „%2$s”.','The theme is installed as planned.'=>'Motyw jest zainstalowany zgodnie z planem.','The theme is active.'=>'Motyw jest aktywny.','A different theme than planned is active.'=>'Aktywny jest inny motyw niż zaplanowany.','Menu “%s” does not exist.'=>'Menu „%s” nie istnieje.','Menu “%s” exists, but contains no items.'=>'Menu „%s” istnieje, ale nie zawiera żadnych pozycji.','The menu contains %1$d item(s), expected %2$d.'=>'Menu zawiera %1$d pozycji, oczekiwano %2$d.','The menu has no link to the page with ID %d.'=>'Menu nie zawiera odnośnika do strony o id %d.','The menu exists and contains the expected links.'=>'Menu istnieje i zawiera oczekiwane odnośniki.','The site still shows posts on the homepage.'=>'Witryna nadal wyświetla wpisy na stronie głównej.','A different page is set as the homepage.'=>'Jako strona główna ustawiona jest inna strona.','No homepage is set.'=>'Nie ustawiono strony głównej.','The homepage is not published.'=>'Strona główna nie jest opublikowana.','The homepage is set and published.'=>'Strona główna jest ustawiona i opublikowana.','Option outside the allowed list.'=>'Opcja spoza dozwolonej listy.','The option has the expected value.'=>'Opcja ma oczekiwaną wartość.','The option does not have the expected value.'=>'Opcja nie ma oczekiwanej wartości.','The tool did not return a term ID.'=>'Narzędzie nie zwróciło identyfikatora terminu.','The term exists.'=>'Termin istnieje.','The term does not exist.'=>'Termin nie istnieje.','No form was created.'=>'Nie utworzono formularza.','The form does not exist in WordPress.'=>'Formularz nie istnieje w WordPressie.','The form exists, but no shortcode was returned.'=>'Formularz istnieje, ale nie zwrócono shortcode.','The contact form exists.'=>'Formularz kontaktowy istnieje.','The contact page does not exist.'=>'Strona kontaktowa nie istnieje.','The contact page does not contain the form.'=>'Strona kontaktowa nie zawiera formularza.','Embedding the form broke the block structure.'=>'Osadzenie formularza uszkodziło strukturę bloków.','The contact page contains the form.'=>'Strona kontaktowa zawiera formularz.','No navigation post was created.'=>'Nie utworzono wpisu nawigacji.','The navigation contains fewer items than planned.'=>'Nawigacja zawiera mniej pozycji niż zaplanowano.','The navigation exists, but the theme does not render it (missing “%s”).'=>'Nawigacja istnieje, ale motyw jej nie renderuje (brak „%s”).','The block theme navigation contains the expected links.'=>'Nawigacja motywu blokowego zawiera oczekiwane odnośniki.','The step did not name a page or an attachment.'=>'Krok nie wskazał strony lub załącznika.','The featured image of page %1$d is %2$d, expected %3$d.'=>'Obrazek wyróżniający strony %1$d to %2$d, oczekiwano %3$d.','Attachment %d does not exist.'=>'Załącznik %d nie istnieje.','The page has the expected featured image set.'=>'Strona ma ustawiony oczekiwany obrazek wyróżniający.','Missing working store pages: %s.'=>'Brakuje działających stron sklepu: %s.','All store pages exist and are assigned.'=>'Wszystkie strony sklepu istnieją i są przypisane.','Setting “%1$s” is “%2$s”, expected “%3$s”.'=>'Ustawienie „%1$s” to „%2$s”, oczekiwano „%3$s”.','The basic store settings match the plan.'=>'Podstawowe ustawienia sklepu są zgodne z planem.','The tool did not return a category ID.'=>'Narzędzie nie zwróciło identyfikatora kategorii.','Category %d does not exist in the product taxonomy.'=>'Kategoria %d nie istnieje w taksonomii produktów.','The category is named “%1$s”, expected “%2$s”.'=>'Kategoria nazywa się „%1$s”, oczekiwano „%2$s”.','The product category exists with the expected name.'=>'Kategoria produktów istnieje z oczekiwaną nazwą.','The tool did not return a product ID.'=>'Narzędzie nie zwróciło identyfikatora produktu.','The product has status “%s”, but must remain a draft.'=>'Produkt ma status „%s”, a musi pozostać szkicem.','The product name does not match the plan.'=>'Nazwa produktu nie zgadza się z planem.','The price is %1$s, expected %2$s.'=>'Cena to %1$s, oczekiwano %2$s.','The product’s categories do not match the plan.'=>'Kategorie produktu nie zgadzają się z planem.','The product image does not match the plan.'=>'Obrazek produktu nie zgadza się z planem.','The product exists as a draft with the expected price.'=>'Produkt istnieje jako szkic z oczekiwaną ceną.','%1$s (status: %2$s)'=>'%1$s (status: %2$s)','All %d pages exist and are published.'=>'Wszystkie %d stron istnieje i jest opublikowanych.','Missing published pages: %s'=>'Brakuje opublikowanych stron: %s','%s (invalid block markup)'=>'%s (nieprawidłowy markup bloków)','The content of every page parses correctly into Gutenberg blocks.'=>'Treść wszystkich stron poprawnie parsuje się do bloków Gutenberga.','Pages with invalid block content: %s'=>'Strony z nieprawidłową treścią blokową: %s','Active theme: %s.'=>'Aktywny motyw: %s.','The active theme does not exist.'=>'Aktywny motyw nie istnieje.','The site has no homepage set.'=>'Witryna nie ma ustawionej strony głównej.','The homepage is id %1$d, expected “%2$s” (id %3$d).'=>'Stroną główną jest id %1$d, oczekiwano „%2$s” (id %3$d).','The homepage points at id %d.'=>'Strona główna wskazuje na id %d.','Site title: “%s”.'=>'Nazwa witryny: „%s”.','The site title is “%1$s”, expected “%2$s”.'=>'Nazwa witryny to „%1$s”, oczekiwano „%2$s”.','The site has no menu at all.'=>'Witryna nie ma żadnego menu.','The menu contains %d item(s).'=>'Menu zawiera %d pozycji.','The menu exists, but contains no items.'=>'Menu istnieje, ale nie zawiera żadnych pozycji.','The menu links to every page in the plan.'=>'Menu zawiera odnośniki do wszystkich stron z planu.','The menu has no link to: %s'=>'Brak w menu odnośników do: %s','Contact Form 7 is active.'=>'Contact Form 7 jest aktywny.','No contact page was found.'=>'Nie znaleziono strony kontaktowej.','The contact page embeds an existing form (id %d).'=>'Strona kontaktowa osadza istniejący formularz (id %d).','The contact page refers to a form that does not exist (“%s”).'=>'Strona kontaktowa odwołuje się do nieistniejącego formularza („%s”).','Checks the store pages (Shop, Cart, Checkout, My account) and recreates only the ones that are actually missing.'=>'Sprawdza strony sklepu (Sklep, Koszyk, Zamówienie, Moje konto) i odtwarza tylko te, których faktycznie brakuje.','Sets the store’s country, currency and units. Cannot change any other WooCommerce setting.'=>'Ustawia kraj, walutę i jednostki sklepu. Nie może zmienić żadnego innego ustawienia WooCommerce.','Creates a product category.'=>'Tworzy kategorię produktów.','Updates a product category previously created by the builder.'=>'Aktualizuje kategorię produktów utworzoną wcześniej przez kreator.','Creates a product as a DRAFT. Does not publish it.'=>'Tworzy produkt jako SZKIC. Nie publikuje go.','Updates a product draft previously created by the builder. Does not publish it.'=>'Aktualizuje szkic produktu utworzony wcześniej przez kreator. Nie publikuje go.','WooCommerce is not fully loaded yet in this request.'=>'WooCommerce nie jest jeszcze w pełni załadowany w tym żądaniu.','WooCommerce does not recognise the country “%s”.'=>'WooCommerce nie zna kraju „%s”.','WooCommerce does not recognise the currency “%s”.'=>'WooCommerce nie zna waluty „%s”.','Unsupported unit.'=>'Nieobsługiwana jednostka.','No category ID given.'=>'Brak identyfikatora kategorii.','Invalid product price.'=>'Nieprawidłowa cena produktu.','No product ID given.'=>'Brak identyfikatora produktu.','Site title'=>'Nazwa witryny','Site tagline / description'=>'Opis / tagline witryny','Week starts on'=>'Pierwszy dzień tygodnia','Timezone'=>'Strefa czasowa','Date format'=>'Format daty','Time format'=>'Format godziny','Posts per page'=>'Wpisów na stronę','Default comment status'=>'Domyślny status komentarzy','Comments require a logged-in user'=>'Komentarze tylko dla zalogowanych','Comment moderation'=>'Moderacja komentarzy','Search engine visibility'=>'Widoczność dla wyszukiwarek','Permalink structure'=>'Struktura bezpośrednich odnośników','What to show on the front page'=>'Co pokazywać na stronie głównej','The option “%s” is not allowed to be written.'=>'Opcja „%s” nie jest dozwolona do zapisu.','The value is longer than %d characters.'=>'Wartość jest dłuższa niż %d znaków.','A number was expected.'=>'Oczekiwano liczby.','The value must be between %1$d and %2$d.'=>'Wartość musi mieścić się w zakresie %1$d–%2$d.','Allowed values: %s.'=>'Dozwolone wartości: %s.','Unknown timezone.'=>'Nieznana strefa czasowa.','Invalid permalink structure.'=>'Nieprawidłowa struktura odnośników.','Unsupported option type.'=>'Nieobsługiwany typ opcji.','Creates (or reuses) a contact form in the active form plugin and returns its shortcode.'=>'Tworzy (lub ponownie wykorzystuje) formularz kontaktowy w aktywnej wtyczce formularzy i zwraca jego shortcode.','Creates or updates the block theme navigation (a wp_navigation post) rendered by the navigation block.'=>'Tworzy lub aktualizuje nawigację motywu blokowego (wpis wp_navigation), którą renderuje blok nawigacji.','Sets a page’s featured image to an attachment that already exists in the media library.'=>'Ustawia obrazek wyróżniający strony na wskazany załącznik, który już istnieje w bibliotece mediów.','Embeds an existing contact form on the given page, if it is not already there.'=>'Osadza istniejący formularz kontaktowy na wskazanej stronie, jeśli jeszcze go tam nie ma.','No supported form plugin is active.'=>'Żadna obsługiwana wtyczka formularzy nie jest aktywna.','The active theme is not a block theme.'=>'Aktywny motyw nie jest motywem blokowym.','Page %d does not exist.'=>'Strona %d nie istnieje.','You are not allowed to edit this page.'=>'Brak uprawnień do edycji tej strony.','Attachment %1$d is not a supported image (%2$s).'=>'Załącznik %1$d nie jest obsługiwanym obrazem (%2$s).','WordPress refused to set the featured image.'=>'WordPress odrzucił ustawienie obrazka wyróżniającego.','Invalid form shortcode.'=>'Nieprawidłowy shortcode formularza.','Creates a new page or post. Returns its id and URL. Content accepts HTML or Gutenberg blocks.'=>'Tworzy nową stronę lub wpis. Zwraca id i adres URL. Treść przyjmuje HTML lub bloki Gutenberga.','Updates an existing page or post (title, content, status, excerpt).'=>'Aktualizuje istniejącą stronę lub wpis (tytuł, treść, status, wyimek).','Moves a page or post to the trash. Not a permanent delete — the content can be restored from the trash.'=>'Przenosi stronę lub wpis do kosza. Nie kasuje trwale — treść można przywrócić z kosza.','Changes one site setting from the allowed list (title, description, timezone, permalinks, comments, visibility).'=>'Zmienia jedno ustawienie witryny z listy dozwolonych (nazwa, opis, strefa czasowa, odnośniki, komentarze, widoczność).','Sets the given page as the site’s homepage, optionally also the posts page.'=>'Ustawia wskazaną stronę jako stronę główną witryny, opcjonalnie także stronę wpisów.','Installs a plugin from the official WordPress.org directory by its slug (e.g. "contact-form-7") and optionally activates it.'=>'Instaluje wtyczkę z oficjalnego katalogu WordPress.org po jej slugu (np. "contact-form-7") i opcjonalnie ją aktywuje.','Activates an already-installed plugin by its slug.'=>'Aktywuje już zainstalowaną wtyczkę po jej slugu.','Deactivates a plugin by its slug. Does not remove its files or data.'=>'Dezaktywuje wtyczkę po jej slugu. Nie usuwa jej plików ani danych.','Installs a theme from the official WordPress.org directory by its slug (e.g. "twentytwentyfour") and optionally activates it.'=>'Instaluje motyw z oficjalnego katalogu WordPress.org po jego slugu (np. "twentytwentyfour") i opcjonalnie go włącza.','Activates an already-installed theme by its slug.'=>'Włącza już zainstalowany motyw po jego slugu.','Creates a navigation menu from the given items (pages by id or custom links) and optionally assigns it to a location in the theme.'=>'Tworzy menu nawigacyjne z podanych pozycji (strony po id lub własne linki) i opcjonalnie przypisuje je do lokalizacji w motywie.','Creates a category, tag or other taxonomy term.'=>'Tworzy kategorię, tag lub inny termin taksonomii.','Allowed types are "page" and "post".'=>'Dozwolone typy to "page" i "post".','There is no post with id %d.'=>'Nie ma wpisu o id %d.','The current user cannot edit this post.'=>'Bieżący użytkownik nie może edytować tego wpisu.','No field to change was given.'=>'Nie podano żadnego pola do zmiany.','The current user cannot delete this post.'=>'Bieżący użytkownik nie może usunąć tego wpisu.','WordPress refused to move the post to the trash.'=>'WordPress odmówił przeniesienia wpisu do kosza.','Id %d does not point to a page.'=>'Id %d nie wskazuje na stronę.','The homepage must be published. Publish it first.'=>'Strona główna musi być opublikowana. Opublikuj ją najpierw.','Invalid plugin slug.'=>'Nieprawidłowy slug wtyczki.','Plugin "%1$s" was not found in the WordPress.org directory: %2$s'=>'Nie znaleziono wtyczki "%1$s" w katalogu WordPress.org: %2$s','The plugin installation failed.'=>'Instalacja wtyczki nie powiodła się.','The plugin was installed, but its main file could not be found.'=>'Wtyczka zainstalowana, ale nie udało się odnaleźć jej pliku głównego.','Plugin "%s" is not installed.'=>'Wtyczka "%s" nie jest zainstalowana.','AI Operator cannot deactivate itself.'=>'AI Operator nie może dezaktywować sam siebie.','Invalid theme slug.'=>'Nieprawidłowy slug motywu.','Theme "%1$s" was not found in the WordPress.org directory: %2$s'=>'Nie znaleziono motywu "%1$s" w katalogu WordPress.org: %2$s','The theme installation failed.'=>'Instalacja motywu nie powiodła się.','The theme was installed, but could not be found.'=>'Motyw zainstalowany, ale nie udało się go odnaleźć.','Could not create the menu.'=>'Nie udało się utworzyć menu.','The theme has no “%s” location.'=>'Motyw nie ma lokalizacji „%s”.','The taxonomy "%s" does not exist.'=>'Taksonomia "%s" nie istnieje.','WordPress AI connectors'=>'Łączniki AI WordPressa','Stopped: the model asked for too many tools in a row in one turn.'=>'Przerwano: model poprosił o zbyt wiele kolejnych narzędzi w jednej turze.','Anthropic, your own API key (%s)'=>'Anthropic, własny klucz API (%s)','OpenAI, your own API key (%s)'=>'OpenAI, własny klucz API (%s)','DoSieci Hub: AI credits from your DoSieci plan'=>'DoSieci Hub: kredyty AI z Twojego planu DoSieci','WordPress AI connectors: your own key, set in Settings > Connectors (WordPress 7.0+)'=>'Łączniki AI WordPressa: własny klucz ustawiony w Ustawienia > Łączniki (WordPress 7.0+)','Anthropic: your own API key'=>'Anthropic: własny klucz API','OpenAI: your own API key'=>'OpenAI: własny klucz API','Install and activate the theme “%s”.'=>'Zainstaluj i włącz motyw „%s”.','The theme is installed and active.'=>'Motyw jest zainstalowany i aktywny.','Install and activate the contact form plugin (Contact Form 7).'=>'Zainstaluj i włącz wtyczkę formularza kontaktowego (Contact Form 7).','The form plugin is active.'=>'Wtyczka formularza jest aktywna.','Page “%s” contains the updated content.'=>'Strona „%s” zawiera zaktualizowaną treść.','Create and publish the page “%s”.'=>'Utwórz i opublikuj stronę „%s”.','Page “%s” exists and is published.'=>'Strona „%s” istnieje i jest opublikowana.','Set the featured image of page “%1$s”: %2$s.'=>'Ustaw obrazek wyróżniający strony „%1$s”: %2$s.','Page “%s” has a featured image set.'=>'Strona „%s” ma ustawiony obrazek wyróżniający.','Main Menu'=>'Menu główne','Create the main menu with %d item(s) and assign it to the theme.'=>'Utwórz menu główne z %d pozycjami i przypisz je do motywu.','The menu exists and is assigned to the theme location.'=>'Menu istnieje i jest przypisane do lokalizacji w motywie.','Set the block theme navigation so the menu is visible on the site.'=>'Ustaw nawigację motywu blokowego, żeby menu było widoczne na stronie.','The block theme renders navigation with links to the pages.'=>'Motyw blokowy renderuje nawigację z odnośnikami do stron.','Set page “%s” as the site’s homepage.'=>'Ustaw stronę „%s” jako stronę główną witryny.','The site displays the chosen page as its homepage.'=>'Witryna wyświetla wskazaną stronę jako stronę główną.','Set the site name to “%s”.'=>'Ustaw nazwę witryny na „%s”.','The site name is set.'=>'Nazwa witryny jest ustawiona.','Create the contact form.'=>'Utwórz formularz kontaktowy.','Embed the contact form on page “%s”.'=>'Osadź formularz kontaktowy na stronie „%s”.','Install and activate WooCommerce.'=>'Zainstaluj i włącz WooCommerce.','WooCommerce is active.'=>'WooCommerce jest aktywny.','Check the store pages (Shop, Cart, Checkout, My account) and recreate any that are missing.'=>'Sprawdź strony sklepu (Sklep, Koszyk, Zamówienie, Moje konto) i odtwórz brakujące.','Set the store basics — country: %1$s, currency: %2$s, units: %3$s / %4$s.'=>'Ustaw podstawy sklepu — kraj: %1$s, waluta: %2$s, jednostki: %3$s / %4$s.','The store’s country, currency and units are set.'=>'Kraj, waluta i jednostki sklepu są ustawione.','Update the product category “%s”.'=>'Zaktualizuj kategorię produktów „%s”.','Create the product category “%s”.'=>'Utwórz kategorię produktów „%s”.','Category “%s” exists.'=>'Kategoria „%s” istnieje.','Update the product draft “%1$s” — %2$s %3$s.'=>'Zaktualizuj szkic produktu „%1$s” — %2$s %3$s.','Create the product draft “%1$s” — %2$s %3$s.'=>'Utwórz szkic produktu „%1$s” — %2$s %3$s.','Product “%s” exists as a draft.'=>'Produkt „%s” istnieje jako szkic.','Tool “%s” has no verifier and cannot enter the plan.'=>'Narzędzie „%s” nie ma weryfikatora i nie może wejść do planu.','Step “%s” must declare a verification.'=>'Krok „%s” musi deklarować weryfikację.','The store country code “%s” is invalid.'=>'Kod kraju sklepu „%s” jest nieprawidłowy.','The currency code “%s” is invalid.'=>'Kod waluty „%s” jest nieprawidłowy.','Unknown weight unit “%s”.'=>'Nieznana jednostka wagi „%s”.','Unknown dimension unit “%s”.'=>'Nieznana jednostka wymiaru „%s”.','Too many categories in the store description.'=>'Zbyt wiele kategorii w opisie sklepu.','A product description must be an object.'=>'Opis produktu musi być obiektem.','Too many products in the store description.'=>'Zbyt wiele produktów w opisie sklepu.','Duplicate name in the %1$s section: “%2$s”.'=>'Powtórzona nazwa w sekcji %1$s: „%2$s”.','Product “%1$s” references a category that does not exist: “%2$s”.'=>'Produkt „%1$s” wskazuje nieistniejącą kategorię „%2$s”.','A category must be a name or an object.'=>'Kategoria musi być nazwą albo obiektem.','A category must have a name.'=>'Kategoria musi mieć nazwę.','The category name is too long.'=>'Nazwa kategorii jest zbyt długa.','A product must have a name.'=>'Produkt musi mieć nazwę.','The product name is too long.'=>'Nazwa produktu jest zbyt długa.','Unknown product image strategy: “%s”.'=>'Nieznana strategia obrazu produktu: „%s”.','A product must have a price.'=>'Produkt musi mieć cenę.','The price “%s” is not a valid number.'=>'Cena „%s” nie jest poprawną liczbą.','The price cannot be negative.'=>'Cena nie może być ujemna.','The price exceeds the allowed limit.'=>'Cena przekracza dopuszczalny limit.','The site description is empty.'=>'Opis witryny jest pusty.','Could not connect to the AI service.'=>'Nie udało się połączyć z usługą AI.','The model did not return a site description.'=>'Model nie zwrócił opisu witryny.','The model’s response is too large.'=>'Odpowiedź modelu jest zbyt duża.','The model did not return valid JSON with a site description.'=>'Model nie zwrócił poprawnego JSON-a z opisem witryny.','The model’s site description is invalid: %s'=>'Opis witryny od modelu jest nieprawidłowy: %s','%s — professional services for individual and business clients.'=>'%s — profesjonalne usługi dla klientów indywidualnych i firm.','Get in touch'=>'Skontaktuj się','What we do'=>'Co robimy','Need a quote?'=>'Potrzebujesz wyceny?','Describe what you need, and we will get back to you with a timeline and a price.'=>'Opisz swój problem, a odpowiemy z propozycją terminu i kosztu.','Write to us'=>'Napisz do nas','Contact'=>'Kontakt','Write or call us'=>'Napisz lub zadzwoń','We are happy to answer any questions about %s’s services.'=>'Chętnie odpowiemy na pytania dotyczące usług firmy %s.','Below is an overview of our services. Every quote is prepared individually.'=>'Poniżej znajdziesz zakres naszych usług. Każdą wycenę przygotowujemy indywidualnie.','%s is a team that values reliability and punctuality. This section is waiting for your own description — add the company’s history, experience and what sets you apart.'=>'%s to zespół, który stawia na rzetelność i terminowość. Ta sekcja czeka na Twój opis — dodaj historię firmy, doświadczenie i to, co Was wyróżnia.','This page (“%s”) is waiting for content. You can fill it in now in the editor.'=>'Ta strona („%s”) czeka na treść. Możesz ją teraz uzupełnić w edytorze.','Fast turnaround'=>'Szybka realizacja','We take on urgent jobs and agree a firm date.'=>'Podejmujemy się zleceń pilnych i umawiamy konkretny termin.','Experienced team'=>'Doświadczony zespół','We work to established standards and best practice.'=>'Pracujemy zgodnie ze sztuką i obowiązującymi normami.','Transparent pricing'=>'Przejrzysta wycena','You know the cost before work starts — no surprises.'=>'Koszt znasz przed rozpoczęciem prac — bez niespodzianek.','Fresh ingredients'=>'Świeże składniki','Our menu is built around what is seasonal and local.'=>'Menu układamy wokół tego, co sezonowe i lokalne.','A place to meet'=>'Miejsce na spotkania','A dining room and reservations for larger groups.'=>'Sala i rezerwacje dla większych grup.','Selected work'=>'Wybrane realizacje','An overview of projects we have worked on.'=>'Przegląd projektów, nad którymi pracowaliśmy.','Process'=>'Proces','How working together looks, step by step.'=>'Jak wygląda współpraca krok po kroku.','none'=>'brak','The image address is empty or too long.'=>'Adres obrazu jest pusty lub zbyt długi.','The image address is not a valid URL.'=>'Adres obrazu nie jest poprawnym URL-em.','Only https addresses are allowed.'=>'Dozwolone są wyłącznie adresy https.','The image address must not contain login credentials.'=>'Adres obrazu nie może zawierać danych logowania.','Only port 443 is allowed.'=>'Dozwolony jest wyłącznie port 443.','The image address does not name a host.'=>'Adres obrazu nie wskazuje hosta.','The image address must name a hostname, not an IP address.'=>'Adres obrazu musi wskazywać nazwę hosta, nie adres IP.','The image address names an internal host.'=>'Adres obrazu wskazuje nazwę wewnętrzną.','The image address must be a fully qualified domain name.'=>'Adres obrazu musi wskazywać pełną nazwę domeny.','The image address must point to an image file (jpg, png, webp, avif).'=>'Adres obrazu musi wskazywać plik obrazu (jpg, png, webp, avif).','The tool refused to run.'=>'Narzędzie odmówiło wykonania.','Step %1$d (%2$s) failed: %3$s'=>'Krok %1$d (%2$s) nie powiódł się: %3$s','The write succeeded, but verifying WordPress’s state failed: %s'=>'Zapis wykonany, ale weryfikacja stanu WordPressa nie powiodła się: %s','Step %1$d (%2$s): %3$s'=>'Krok %1$d (%2$s): %3$s','Step “%s” does not declare a verification, so its effect cannot be confirmed.'=>'Krok „%s” nie deklaruje weryfikacji, więc nie można potwierdzić jego skutku.','No reversible steps to undo.'=>'Brak odwracalnych kroków do cofnięcia.','Create “%s”.'=>'Utwórz „%s”.','Use the existing page “%1$s” (id %2$d) without changing its content.'=>'Użyj istniejącej strony „%1$s” (id %2$d) bez zmiany treści.','Update “%1$s” (id %2$d), previously created by the builder.'=>'Zaktualizuj „%1$s” (id %2$d) utworzoną wcześniej przez kreator.','Conflict: “%1$s” (id %2$d) was edited by hand — the builder will not overwrite it.'=>'Konflikt: „%1$s” (id %2$d) została zmieniona ręcznie — kreator jej nie nadpisze.','Final audit: %1$d/%2$d checks passed.'=>'Audyt końcowy: %1$d/%2$d kontroli zaliczonych.','Final audit: %1$d of %2$d checks failed — %3$s'=>'Audyt końcowy: %1$d z %2$d kontroli nie powiodło się — %3$s','The blueprint must define at least one page.'=>'Opis witryny musi zawierać przynajmniej jedną stronę.','Site type “Store” requires store data: country, currency, at least one category and at least one product.'=>'Rodzaj witryny „Sklep” wymaga danych sklepu: kraju, waluty, przynajmniej jednej kategorii i produktu.','“%1$s” must be one of: %2$s.'=>'„%1$s” musi być jedną z wartości: %2$s.','“%s” is required.'=>'„%s” jest wymagane.','“%1$s” exceeds %2$d characters.'=>'„%1$s” przekracza %2$d znaków.','“%s” must be a list.'=>'„%s” musi być listą.','“%s” must contain only strings.'=>'„%s” może zawierać wyłącznie ciągi znaków.','“%1$s” is limited to %2$d entries.'=>'„%1$s” jest ograniczone do %2$d elementów.','Tool activity'=>'Aktywność narzędzi','Every tool call the operator attempted, including the ones that were refused. Secrets are never recorded here.'=>'Każda próba wywołania narzędzia — również odrzucona. Sekrety nigdy nie są tu zapisywane.','When'=>'Kiedy','User'=>'Użytkownik','Tool'=>'Narzędzie','Outcome'=>'Wynik','Reason'=>'Powód','Request ID'=>'Request ID','No activity recorded yet.'=>'Brak zarejestrowanej aktywności.','DoSieci AI'=>'DoSieci AI','Chat'=>'Czat','Site Builder'=>'Kreator witryny','Connection'=>'Połączenie','History'=>'Historia','Activity'=>'Aktywność','Settings'=>'Ustawienia','You'=>'Ty','Operator'=>'Operator','The operator is thinking…'=>'Operator myśli…','Applying the approved change…'=>'Wykonuję zatwierdzoną zmianę…','Something went wrong.'=>'Wystąpił błąd.','Tool ran'=>'Wykonano narzędzie','Tool denied'=>'Odmówiono narzędzia','The operator is asking for approval to make a change.'=>'Operator prosi o zgodę na zmianę.','Approve this change to the site'=>'Zatwierdź zmianę na witrynie','Approve and run'=>'Zatwierdź i wykonaj','Reject'=>'Odrzuć','Note: this action removes content. It can be restored from the trash.'=>'Uwaga: to działanie usuwa treść. Można ją przywrócić z kosza.','You are not allowed to do this.'=>'Brak uprawnień.','Enter both the Hub address and the pairing token.'=>'Podaj adres Hub oraz token parowania.','Connected to DoSieci.'=>'Połączono z DoSieci.','Disconnected locally. Remember to also revoke this site’s key in the DoSieci panel.'=>'Rozłączono lokalnie. Pamiętaj, aby unieważnić klucz tej witryny również w panelu DoSieci.','The message is empty.'=>'Pusta wiadomość.','There is no pending action to approve.'=>'Nie ma oczekującej akcji do zatwierdzenia.','This action is out of date. Reload the page.'=>'Ta akcja jest już nieaktualna. Odśwież stronę.','Mode:'=>'Tryb:','The operator has %1$d tools, %2$d of which can change the site. Every change needs your confirmation in the chat.'=>'Operator ma %1$d narzędzi, w tym %2$d zmieniających witrynę. Każda zmiana wymaga Twojego potwierdzenia w czacie.','The operator has access to %d read-only tools. None of them change data on this site.'=>'Operator ma dostęp do %d narzędzi tylko do odczytu. Żadne z nich nie zmienia danych na tej witrynie.','Allow changes to the site'=>'Włącz zmiany na witrynie','Message to the operator'=>'Wiadomość do operatora','e.g. Build a homepage with an about section and add it to the menu'=>'np. Zbuduj stronę główną z sekcją o firmie i dodaj ją do menu','e.g. Check the site’s technical health and its largest autoloaded options'=>'np. Sprawdź stan techniczny witryny i największe autoloadowane opcje','Send'=>'Wyślij','This site is not connected to DoSieci yet. %1$s or use your own AI key in %2$s.'=>'Ta witryna nie jest jeszcze połączona z DoSieci. %1$s albo użyj własnego klucza API w %2$s.','Go to Connection'=>'Przejdź do połączenia','WordPress AI connectors need WordPress 7.0 or later with AI features enabled, which this site does not have. Choose another mode in %s.'=>'Łączniki AI WordPressa wymagają WordPressa 7.0 lub nowszego z włączonymi funkcjami AI, których ta witryna nie ma. Wybierz inny tryb w %s.','No AI provider is connected under Settings > Connectors yet. Connect one there, or choose another mode in %s.'=>'Żaden dostawca AI nie jest jeszcze połączony w Ustawienia > Łączniki. Połącz go tam albo wybierz inny tryb w %s.','A provider with your own API key is selected, but no key is saved. Add it in %s.'=>'Wybrano dostawcę z własnym kluczem API, ale żaden klucz nie został zapisany. Dodaj go w %s.','WordPress AI connectors (%s) — your own key, no DoSieci credits used'=>'Łączniki AI WordPressa (%s) — własny klucz, kredyty DoSieci nie są zużywane','your own API key, model %s — no DoSieci credits used'=>'własny klucz API, model %s — kredyty DoSieci nie są zużywane','DoSieci Hub — requests are billed from your plan’s credits'=>'DoSieci Hub — zapytania rozliczane z kredytów Twojego planu','Your DoSieci plan has run out of AI credits. Top them up with DoSieci, or switch to your own AI key in the settings.'=>'Wyczerpano kredyty AI w Twoim planie DoSieci. Doładuj je w panelu DoSieci lub przełącz wtyczkę na własny klucz API w Ustawieniach.','This site is not connected to DoSieci. Pair it on the Connection screen, or choose your own AI key in the settings.'=>'Ta witryna nie jest połączona z DoSieci. Przejdź do zakładki Połączenie albo ustaw własny klucz API w Ustawieniach.','This site’s connection to DoSieci was revoked. Pair it again.'=>'Połączenie tej witryny zostało unieważnione. Sparuj ją ponownie.','A provider with your own API key is selected, but no key is saved. Add it in the settings.'=>'Wybrano własnego dostawcę AI, ale nie zapisano klucza API. Uzupełnij go w Ustawieniach.','The AI provider rejected your API key. Check that it is correct and active.'=>'Dostawca AI odrzucił Twój klucz API. Sprawdź, czy jest poprawny i aktywny.','Your account with the AI provider has no funds left. Top it up with the provider.'=>'Twoje konto u dostawcy AI nie ma środków. Doładuj je po stronie dostawcy.','Too many requests to the model. Try again in a moment.'=>'Zbyt wiele zapytań do modelu. Spróbuj ponownie za chwilę.','The AI provider rejected the request. Check the model name in the settings.'=>'Dostawca AI odrzucił zapytanie. Sprawdź nazwę modelu w Ustawieniach.','The AI model is temporarily unavailable. Try again in a moment.'=>'Model AI jest chwilowo niedostępny. Spróbuj ponownie za chwilę.','The model reached its output limit before it finished answering. Try a shorter request, or split the task into steps.'=>'Model osiągnął limit odpowiedzi, zanim skończył. Spróbuj krótszego zapytania albo podziel zadanie na kroki.','The DoSieci AI gateway is misconfigured. Contact DoSieci support.'=>'Brama AI po stronie DoSieci jest niepoprawnie skonfigurowana. Skontaktuj się ze wsparciem.','WordPress AI connectors are not available on this site: they need WordPress 7.0 or later with AI features enabled. Choose another mode in the settings.'=>'Łączniki AI WordPressa nie są dostępne na tej witrynie: wymagają WordPressa 7.0 lub nowszego z włączonymi funkcjami AI. Wybierz inny tryb w Ustawieniach.','None of the AI providers connected in Settings > Connectors has a model that can use tools. Connect a provider (for example OpenAI, Anthropic or Google), or choose another mode.'=>'Żaden z dostawców AI połączonych w Ustawienia > Łączniki nie ma modelu obsługującego narzędzia. Połącz dostawcę (np. OpenAI, Anthropic lub Google) albo wybierz inny tryb.','Could not connect to the AI service. Check the site’s network connection.'=>'Nie udało się połączyć z usługą AI. Sprawdź połączenie sieciowe witryny.','The AI service returned an error. Try again in a moment.'=>'Usługa AI zwróciła błąd. Spróbuj ponownie za chwilę.','History cleared.'=>'Historia wyczyszczona.','Conversation history'=>'Historia rozmów','No history is saved yet.'=>'Brak zapisanej historii.','Tool (request)'=>'Narzędzie (żądanie)','Tool (result)'=>'Narzędzie (wynik)','Clear my history'=>'Wyczyść moją historię','AI Operator settings'=>'Ustawienia AI Operator','AI provider'=>'Dostawca AI','Where the model comes from'=>'Skąd brać model','The DoSieci Hub mode spends credits from your DoSieci plan and needs no key of your own. Every other mode connects directly to the provider: no DoSieci credits are used, and you pay the provider directly.'=>'Tryb DoSieci Hub zużywa kredyty z Twojego planu i nie wymaga własnego klucza. Pozostałe tryby łączą się bezpośrednio z dostawcą — nie zużywają kredytów DoSieci, a za zapytania płacisz bezpośrednio dostawcy.','API key'=>'Klucz API','paste a key to set or change it'=>'wklej klucz, aby ustawić lub zmienić','Saved key:'=>'Zapisany klucz:','remove the saved key'=>'usuń zapisany klucz','Used only for the “Anthropic” and “OpenAI” modes above; the Hub and WordPress AI connectors modes ignore it. Empty = leave the current key unchanged. The key is stored in this site’s database and sent only to the chosen provider over HTTPS — never to DoSieci and never to the audit log.'=>'Używany tylko dla trybów „Anthropic” i „OpenAI” powyżej; tryb Hub i Łączniki AI WordPressa go ignorują. Puste pole = zostaw obecny klucz bez zmian. Klucz jest zapisywany w bazie tej witryny i wysyłany wyłącznie do wybranego dostawcy po HTTPS — nie trafia do DoSieci ani do logu audytowego.','Model'=>'Model','Empty = let WordPress pick a suitable model from your connected providers. Fill this in only to prefer a specific one.'=>'Puste = WordPress sam wybierze odpowiedni model spośród połączonych dostawców. Wypełnij tylko, jeśli chcesz wskazać konkretny.','Empty = the default model for the chosen provider (currently: %s). Not used in Hub mode.'=>'Puste = domyślny model dla wybranego dostawcy (teraz: %s). Nieużywane w trybie Hub.','Changes to the site'=>'Zmiany na witrynie','Write tools'=>'Narzędzia zapisu','Let the operator change this site (create content, install themes and plugins, change settings).'=>'Pozwól operatorowi zmieniać tę witrynę (tworzyć treści, instalować motywy i wtyczki, zmieniać ustawienia).','Turning this on does NOT mean the operator acts without oversight.'=>'Włączenie tej opcji NIE oznacza, że operator działa bez kontroli.','Every single change still needs its own “Approve” click in the chat, and each one only acts within the logged-in WordPress user’s own permissions. Without this option, write tools are not even registered — the model does not know they exist.'=>'Każda pojedyncza zmiana wymaga osobnego kliknięcia „Zatwierdź” w czacie, i każda działa wyłącznie w granicach uprawnień zalogowanego użytkownika WordPressa. Bez tej opcji narzędzia zapisu nie są w ogóle rejestrowane — model o nich nie wie.','Plugin data'=>'Dane wtyczki','Data removal'=>'Usuwanie danych','Delete all of this plugin’s data when it is uninstalled (pairing, API key, history, audit log).'=>'Usuń wszystkie dane wtyczki przy jej odinstalowaniu (parowanie, klucz API, historia, log audytowy).','Off by default: deactivating or uninstalling the plugin does not delete data until you deliberately turn this on.'=>'Domyślnie wyłączone: deaktywacja i odinstalowanie nie kasują danych, dopóki świadomie tego nie włączysz.','Save'=>'Zapisz','Available tools'=>'Dostępne narzędzia','Registered tools: %1$d, of which %2$d can change data.'=>'Zarejestrowanych narzędzi: %1$d, w tym zmieniających dane: %2$d.','Description'=>'Opis','Required capability'=>'Wymagane uprawnienie','Risk level'=>'Poziom ryzyka','This site’s WordPress version does not support AI connectors (needs WordPress 7.0+ with AI features enabled).'=>'Wersja WordPressa tej witryny nie obsługuje Łączników AI (wymaga WordPressa 7.0+ z włączonymi funkcjami AI).','No provider is connected yet. Add one under %s.'=>'Żaden dostawca nie jest jeszcze połączony. Dodaj go w %s.','Settings > Connectors'=>'Ustawienia > Łączniki','Connected: %s.'=>'Połączono: %s.','Saved, but the chosen provider needs an API key — the chat will not work until you add one.'=>'Zapisano, ale wybrany dostawca wymaga klucza API — czat nie zadziała, dopóki go nie uzupełnisz.','Saved, but no AI provider is connected under Settings > Connectors yet — the chat will not work until you connect one.'=>'Zapisano, ale żaden dostawca AI nie jest jeszcze połączony w Ustawienia > Łączniki — czat nie zadziała, dopóki go nie połączysz.','Saved.'=>'Zapisano.','Describe the site you want to build.'=>'Opisz witrynę, którą chcesz zbudować.','Could not prepare the site description.'=>'Nie udało się przygotować opisu witryny.','Invalid site description.'=>'Nieprawidłowy opis witryny.','Site Builder mode requires write tools to be enabled in Settings.'=>'Tryb budowania witryny wymaga włączenia narzędzi zapisu w Ustawieniach.','This plan is out of date. Refresh the page and review it again.'=>'Ten plan jest nieaktualny. Odśwież stronę i przejrzyj go ponownie.','No plan ID given.'=>'Brak identyfikatora planu.','Plan not found.'=>'Nie znaleziono planu.','What I understood'=>'Co zrozumiałem','Business'=>'Firma','Type'=>'Rodzaj','Pages'=>'Strony','Features'=>'Funkcje','Store'=>'Sklep','%d category'=>'%d kategoria' . "\0" . '%d kategorie' . "\0" . '%d kategorii','%d product'=>'%d produkt' . "\0" . '%d produkty' . "\0" . '%d produktów','Build plan — %d step'=>'Plan budowy — %d krok' . "\0" . 'Plan budowy — %d kroki' . "\0" . 'Plan budowy — %d kroków','Review every step. You approve them together — nothing runs before that.'=>'Przejrzyj wszystkie kroki. Zatwierdzasz je razem — nic nie wykona się wcześniej.',' (irreversible)'=>' (nieodwracalne)','Approve the whole plan'=>'Zatwierdź cały plan','Cancel'=>'Anuluj','Final audit'=>'Audyt końcowy','Progress — %1$d / %2$d'=>'Postęp — %1$d / %2$d','Pause'=>'Wstrzymaj','Stop'=>'Przerwij','Resume'=>'Wznów','Undo the changes made'=>'Cofnij wprowadzone zmiany','Preparing…'=>'Przygotowuję…','Prepare description'=>'Przygotuj opis','Site type “Store” is selected — fill in the store data below.'=>'Wybrano rodzaj „Sklep” — uzupełnij dane sklepu poniżej.','Enter a valid store country code (e.g. PL).'=>'Podaj prawidłowy kod kraju sklepu (np. PL).','Enter a valid currency code (e.g. PLN).'=>'Podaj prawidłowy kod waluty (np. PLN).','Add at least one product category.'=>'Dodaj przynajmniej jedną kategorię produktów.','Add at least one product.'=>'Dodaj przynajmniej jeden produkt.','Every product must have a name.'=>'Każdy produkt musi mieć nazwę.','Product “%s” has an invalid price.'=>'Produkt „%s” ma nieprawidłową cenę.','Product “%s” has no assigned category.'=>'Produkt „%s” nie ma przypisanej kategorii.','Site Builder requires write tools to be enabled in Settings. Without them, the AI can only read the site.'=>'Kreator wymaga włączenia narzędzi zapisu w zakładce Ustawienia. Bez nich AI może tylko czytać witrynę.','Describe the site you want to build. You’ll see the full action plan and approve it with one click — no step runs before that.'=>'Opisz witrynę, którą chcesz zbudować. Zobaczysz pełny plan działań i zatwierdzisz go jednym kliknięciem — żaden krok nie wykona się wcześniej.','Describe the site in your own words'=>'Opisz witrynę własnymi słowami','Build me a professional website for HydroMax, a plumbing company in Warsaw. Pages: Home, Services, About, Our Work, Contact. Add a contact form. Colors: navy blue and white.'=>'Zbuduj mi profesjonalną stronę firmy hydraulicznej HydroMax w Warszawie. Strony: Start, Oferta, O nas, Realizacje, Kontakt. Dodaj formularz kontaktowy. Kolory granatowy i biały.','The AI will only prepare a DESCRIPTION of the site for you to review. Nothing will be installed or changed at this stage.'=>'AI przygotuje wyłącznie OPIS witryny do Twojej akceptacji. Nic nie zostanie zainstalowane ani zmienione na tym etapie.','Service business'=>'Firma usługowa','Landing page'=>'Landing page','Portfolio'=>'Portfolio','Restaurant'=>'Restauracja','Blog'=>'Blog','Business name'=>'Nazwa firmy','Site type'=>'Rodzaj witryny','Separate with commas. The first page will become the homepage.'=>'Oddziel przecinkami. Pierwsza strona zostanie stroną główną.','Contact form'=>'Formularz kontaktowy','Prepare plan'=>'Przygotuj plan','Store details'=>'Dane sklepu','Country (ISO code, e.g. PL)'=>'Kraj (kod ISO, np. PL)','Currency (e.g. PLN)'=>'Waluta (np. PLN)','Weight unit'=>'Jednostka wagi','Dimension unit'=>'Jednostka wymiaru','Categories'=>'Kategorie','Name'=>'Nazwa','+ Add category'=>'+ Dodaj kategorię','Products'=>'Produkty','Price'=>'Cena','Category'=>'Kategoria','+ Add product'=>'+ Dodaj produkt','Connection to DoSieci'=>'Połączenie z DoSieci','Status'=>'Status','Connected'=>'Połączono','Hub address'=>'Adres Hub','Site ID'=>'Identyfikator witryny','Key ID'=>'Identyfikator klucza','Paired'=>'Sparowano','The plugin never displays or returns this site’s signing secret. If you suspect it has leaked, ask DoSieci to revoke the key and pair the site again.'=>'Sekret podpisujący tej witryny nigdy nie jest wyświetlany ani zwracany przez wtyczkę. Jeśli podejrzewasz jego wyciek, unieważnij klucz w panelu DoSieci i sparuj witrynę ponownie.','Disconnect this site'=>'Rozłącz tę witrynę','Pair this site with DoSieci to use the AI credits from your DoSieci plan: no AI provider account or API key of your own is needed. DoSieci gives you a one-time pairing token; paste it below.'=>'Sparuj tę witrynę z DoSieci, aby korzystać z kredytów AI Twojego planu DoSieci: nie potrzebujesz konta u dostawcy AI ani własnego klucza API. DoSieci przekazuje jednorazowy token parowania; wklej go poniżej.','<a href="%1$s" target="_blank" rel="noopener">How to get a pairing token</a>. Prefer your own AI key (WordPress AI connectors, OpenAI or Anthropic)? Choose it in the <a href="%2$s">settings</a>; no pairing is needed then.'=>'<a href="%1$s" target="_blank" rel="noopener">Jak zdobyć token parowania</a>. Wolisz własny klucz AI (Łączniki AI WordPressa, OpenAI albo Anthropic)? Wybierz go w <a href="%2$s">ustawieniach</a>; wtedy parowanie nie jest potrzebne.','Must start with https://'=>'Musi zaczynać się od https://','Pairing token'=>'Token parowania','The token works once and expires soon after it is issued.'=>'Token jest jednorazowy i krótko ważny.','Connect to DoSieci'=>'Połącz z DoSieci']];